questions.model_answer:
function prioritizeBacklog(items) {
  const getRank = (item) => {
    if (item.urgent && item.important) return 1;
    if (!item.urgent && item.important) return 2;
    if (item.urgent && !item.important) return 3;
    return 4;
  };
  return items
    .filter(item => item.estimatedCost <= item.expectedBenefit)
    .map((item, idx) => ({ id: item.id, rank: getRank(item), viable: true, _idx: idx }))
    .sort((a, b) => a.rank - b.rank || a._idx - b._idx)
    .map(({ id, rank, viable }) => ({ id, rank, viable }));
}

