questions.model_answer:
function generateSalesReport(records, formatter) {
  const valid = records.filter(r => !r.refunded);
  const totalRevenue = valid.reduce((sum, r) => sum + r.amount, 0);
  const dto = {
    validCount: valid.length,
    totalRevenue,
    items: valid.map(r => r.item)
  };
  return formatter(dto);
}

