questions.model_answer:
function simulateMultiYearChanges(requests, shapePenaltyFactor) {
  let completedCount = 0;
  const blockedByCost = [];
  let totalSpent = 0;
  requests.forEach((req, i) => {
    const actualCost = Number((req.scopeCost * Math.pow(shapePenaltyFactor, i)).toFixed(2));
    if (actualCost <= req.benefit) {
      completedCount++;
      totalSpent = Number((totalSpent + actualCost).toFixed(2));
    } else {
      blockedByCost.push(req.name);
    }
  });
  return { completedCount, blockedByCost, totalSpent };
}
